-- 059b · Plantilla 'contrato_obra_contratista' versión 1.0: el JSON oficial tal cual (fuente única del texto).
-- Verificado al cargar: md5(contenido::text) = cf5d49bd70df3a8c74a9d5621b27ecd8 y md5 del texto de las 23 cláusulas = 4e15a610c4ac8d2a19e88a1203565a3b.
-- Una versión publicada no se edita: un cambio de texto = insertar la versión 1.1 y marcar la 1.0 vigente = false.
insert into public.contrato_plantillas (plantilla, version, modalidad, contenido) values ('contrato_obra_contratista', '1.0', 'ADMINISTRACION_DELEGADA', $j${"plantilla":"contrato_obra_contratista","version":"1.0","fecha_version":"2026-10-15","modalidad_aplicable":["administracion_delegada"],"regla_partes":"HABITATUM S.A.S. NO es parte ni firmante. Firman el Contratante (propietario/s del proyecto) y el Contratista. HABITATUM se nombra como Administrador de Obra que actúa en nombre y representación del Contratante (Cláusula 3). No se menciona el contrato de administración delegada con el cliente ni por qué se eligió al contratista.","documento":{"encabezado_subtitulo":"Contrato de obra con contratista","titulo":"CONTRATO DE OBRA – {{actividad_mayusculas}}","subtitulo":"No. {{numero_contrato}}","pie_izquierdo":"HABITATUM S.A.S. · Administrador de Obra","cierre":"— Sin texto posterior a esta línea —"},"partes":{"plantilla":"Entre los suscritos: de una parte, {{contratante_identificacion}} (en adelante el \"Contratante\"); y de la otra, {{contratista_identificacion}} (en adelante el \"Contratista\"), y conjuntamente las \"Partes\", hemos convenido celebrar el presente Contrato de Obra (el \"Contrato\"), que se regirá por las Condiciones Particulares, las Condiciones Generales, sus anexos y, en lo no previsto, por las normas civiles y comerciales aplicables. El Contratante ha designado a HABITATUM S.A.S., NIT 900.896.011-0, como Administrador de Obra, quien actuará en su nombre y representación en los términos de la Cláusula 3, sin ser parte de este Contrato. El Contratista declara ser un empresario independiente, experto en la especialidad objeto de este Contrato, que cuenta con los medios técnicos y humanos para ejecutarla con plena autonomía.","contratante_persona_natural":"{{NOMBRE_MAYUSCULAS}}, mayor de edad, identificado(a) con cédula de ciudadanía No. {{cedula}}","contratante_varios":"Unir cada propietario con ', ' y ' y ' antes del último; luego agregar: ', quienes obran en nombre propio como propietarios del predio donde se ejecuta la Obra y responden solidariamente por las obligaciones a su cargo'. Si es uno solo: ', quien obra en nombre propio como propietario(a) del predio donde se ejecuta la Obra'.","contratante_persona_juridica":"{{RAZON_SOCIAL}}, sociedad identificada con NIT {{nit}}, representada legalmente por {{rep_legal}}, identificado(a) con cédula de ciudadanía No. {{cc_rep_legal}}","contratista_persona_natural":"{{NOMBRE_MAYUSCULAS}}, mayor de edad, identificado(a) con cédula de ciudadanía No. {{cedula}}, quien obra en nombre propio","contratista_persona_juridica":"{{RAZON_SOCIAL}}, sociedad identificada con NIT {{nit}}, representada legalmente por {{rep_legal}}, identificado(a) con cédula de ciudadanía No. {{cc_rep_legal}}"},"condiciones_particulares":[{"seccion":"1. CONTRATANTE","campos":[{"clave":"contratante_nombre","etiqueta":"Nombre","origen":"proyecto.propietarios (nombres unidos con \" y \")","obligatorio":true,"tipo":"texto"},{"clave":"contratante_direccion","etiqueta":"Dirección","origen":"proyecto.propietario_principal.direccion","obligatorio":false,"tipo":"texto"},{"clave":"contratante_telefono","etiqueta":"Teléfono","origen":"proyecto.propietario_principal.telefono","obligatorio":false,"tipo":"texto"},{"clave":"contratante_correo","etiqueta":"Correo","origen":"proyecto.propietario_principal.correo","obligatorio":false,"tipo":"texto"}]},{"seccion":"2. CONTRATISTA","campos":[{"clave":"contratista_nombre","etiqueta":"Nombre","origen":"proveedor.nombre","obligatorio":true,"tipo":"texto"},{"clave":"contratista_direccion","etiqueta":"Dirección","origen":"proveedor.direccion","obligatorio":false,"tipo":"texto"},{"clave":"contratista_telefono","etiqueta":"Teléfono","origen":"proveedor.telefono","obligatorio":false,"tipo":"texto"},{"clave":"contratista_correo","etiqueta":"Correo","origen":"proveedor.correo","obligatorio":false,"tipo":"texto"},{"clave":"contratista_regimen","etiqueta":"Régimen tributario y soporte de cobro","origen":"proveedor.regimen_iva + soporte_cobro","obligatorio":true,"tipo":"texto","nota":"Ej.: \"No responsable de IVA · Cuenta de cobro a nombre del Contratante\" o \"Responsable de IVA · Factura electrónica a nombre del Contratante\""},{"clave":"encargado_obra","etiqueta":"Encargado permanente en obra","origen":"contrato.encargado_obra","obligatorio":false,"tipo":"texto"}]},{"seccion":"3. ADMINISTRADOR DE OBRA (designado por el Contratante – no es parte)","campos":[{"clave":"admin_razon_social","etiqueta":"Razón social","origen":"fijo","obligatorio":true,"tipo":"fijo","valor_por_defecto":"HABITATUM S.A.S. – NIT 900.896.011-0"},{"clave":"admin_director","etiqueta":"Director de obra","origen":"proyecto.director_obra","obligatorio":true,"tipo":"texto","valor_por_defecto":"Arq. Andrés David Hincapié Cadavid"},{"clave":"admin_telefono","etiqueta":"Teléfono","origen":"fijo","obligatorio":true,"tipo":"fijo","valor_por_defecto":"321 748 4979"},{"clave":"admin_correo","etiqueta":"Correo","origen":"fijo","obligatorio":true,"tipo":"fijo","valor_por_defecto":"direcciondeproyectos@infohabitatum.com"}]},{"seccion":"4. OBRA","campos":[{"clave":"proyecto_nombre","etiqueta":"Proyecto","origen":"proyecto.nombre","obligatorio":true,"tipo":"texto"},{"clave":"proyecto_ubicacion","etiqueta":"Ubicación","origen":"proyecto.ubicacion","obligatorio":true,"tipo":"texto"}]},{"seccion":"5. OBJETO Y ALCANCE","campos":[{"clave":"actividad","etiqueta":"Actividad","origen":"contrato.actividad","obligatorio":true,"tipo":"texto"},{"clave":"alcance","etiqueta":"Alcance","origen":"contrato.alcance","obligatorio":true,"tipo":"texto_largo","nota":"Debe incluir las frases INCLUYE: ... y NO INCLUYE: ... (materiales, equipos mayores, etc.)"}]},{"seccion":"6. CONDICIONES ECONÓMICAS","campos":[{"clave":"modalidad_precio","etiqueta":"Modalidad de precio","origen":"fijo","obligatorio":true,"tipo":"fijo","valor_por_defecto":"Precios unitarios fijos (Anexo 1)"},{"clave":"valor","etiqueta":"Valor estimado del contrato","origen":"calculado: total Anexo 1 (subtotal + A + I + U + IVA según régimen)","obligatorio":true,"tipo":"moneda"},{"clave":"valor_letras","etiqueta":"Valor en letras","origen":"calculado: valor en letras en español + \" PESOS M/CTE. El valor definitivo resulta de las cantidades ejecutadas.\"","obligatorio":true,"tipo":"texto"},{"clave":"regimen","etiqueta":"Régimen tributario","origen":"contrato.regimen (IVA | AIU | Sin IVA)","obligatorio":true,"tipo":"lista"},{"clave":"anticipo_pct","etiqueta":"Anticipo","origen":"contrato.anticipo_pct","obligatorio":true,"tipo":"porcentaje","valor_por_defecto":0},{"clave":"anticipo_valor","etiqueta":"Valor del anticipo","origen":"calculado: valor × anticipo_pct (omitir fila si anticipo = 0)","obligatorio":true,"tipo":"moneda"},{"clave":"retencion_pct","etiqueta":"Retención de garantía","origen":"contrato.retencion_pct","obligatorio":true,"tipo":"porcentaje","valor_por_defecto":0.1},{"clave":"cortes_pagos","etiqueta":"Cortes y pagos","origen":"contrato.cortes_pagos","obligatorio":true,"tipo":"texto","valor_por_defecto":"Quincenales. Cada corte aprobado se paga dentro de uno (1) a tres (3) días calendario siguientes a su aprobación y a la entrega de los documentos."},{"clave":"medio_pago","etiqueta":"Medio de pago","origen":"contrato.medio_pago","obligatorio":true,"tipo":"texto","valor_por_defecto":"Efectivo o transferencia bancaria a la cuenta del Contratista, según se acuerde para cada corte."}]},{"seccion":"7. PLAZO Y HORARIO","campos":[{"clave":"plazo","etiqueta":"Plazo de ejecución","origen":"contrato.plazo_texto","obligatorio":true,"tipo":"texto","valor_por_defecto":"[N] meses contados a partir de la firma del Contrato"},{"clave":"horario","etiqueta":"Horario de la obra","origen":"proyecto.horario_obra","obligatorio":true,"tipo":"texto","valor_por_defecto":"Lunes a viernes de 7:00 a.m. a 5:00 p.m. y sábados de 7:00 a.m. a 12:00 m."}]},{"seccion":"8. GARANTÍA DE LOS TRABAJOS","campos":[{"clave":"garantia","etiqueta":"Garantía de calidad","origen":"contrato.garantia_meses","obligatorio":true,"tipo":"texto","valor_por_defecto":"Doce (12) meses contados desde el Acta de Recibo Final"},{"clave":"reclamos","etiqueta":"Atención de reclamos","origen":"fijo/editable","obligatorio":true,"tipo":"texto","valor_por_defecto":"Inicio de la corrección dentro de cinco (5) días hábiles del aviso; urgencias en 24 horas"}]},{"seccion":"9. FIRMA Y ANEXOS","campos":[{"clave":"lugar_fecha","etiqueta":"Lugar y fecha de firma","origen":"contrato.lugar_firma + contrato.fecha_firma (formato: \"El Retiro, Antioquia, 19 de octubre de 2026\", mes en minúscula)","obligatorio":true,"tipo":"texto"},{"clave":"domicilio","etiqueta":"Domicilio contractual","origen":"proyecto.municipio","obligatorio":true,"tipo":"texto"},{"clave":"anexos","etiqueta":"Anexos","origen":"fijo","obligatorio":true,"tipo":"fijo","valor_por_defecto":"Anexo 1. Cantidades y precios · Anexo 2. Condiciones técnicas · Planos y especificaciones de la Obra"}]}],"regla_campos_vacios":"Un campo opcional sin valor NO se imprime (se omite la fila completa). Nunca imprimir filas en blanco ni marcadores [ ] en el documento final.","garantias_exigidas":{"columnas":["Amparo","%","Base","Valor asegurado","Vigencia"],"valor_asegurado":"% × valor del contrato (anticipo: % × valor del anticipo)","solo_imprimir_las_que_aplican":true,"opciones":[{"clave":"cumplimiento","amparo":"Cumplimiento del contrato","pct":0.1,"base":"Valor del contrato","vigencia":"Plazo del contrato + 4 meses","activa_por_defecto":true},{"clave":"anticipo","amparo":"Buen manejo y correcta inversión del anticipo","pct":1.0,"base":"Valor del anticipo","vigencia":"Plazo del contrato + 4 meses","activa_por_defecto":false},{"clave":"salarios","amparo":"Pago de salarios, prestaciones sociales e indemnizaciones laborales","pct":0.1,"base":"Valor del contrato","vigencia":"Plazo del contrato + 3 años","activa_por_defecto":true},{"clave":"estabilidad","amparo":"Estabilidad y calidad de la obra","pct":0.2,"base":"Valor final del contrato","vigencia":"2 años desde el Acta de Recibo Final","activa_por_defecto":true},{"clave":"calidad_bienes","amparo":"Calidad y correcto funcionamiento de los bienes suministrados","pct":0.2,"base":"Valor del contrato","vigencia":"2 años desde el Acta de Recibo Final","activa_por_defecto":false,"nota":"Activar solo si el contratista suministra materiales o equipos"},{"clave":"rce","amparo":"Responsabilidad civil extracontractual","pct":0.2,"base":"Valor del contrato","vigencia":"Plazo del contrato y sus prórrogas","activa_por_defecto":true}],"nota_al_pie":"Asegurado y beneficiario: el Contratante; HABITATUM S.A.S. como beneficiario adicional cuando la aseguradora lo permita. En responsabilidad civil extracontractual, asegurados adicionales el Contratante y HABITATUM S.A.S. El valor de estabilidad se ajusta al valor final en la liquidación."},"clausulas":[{"numero":1,"titulo":"DEFINICIONES","parrafos":[{"tipo":"parrafo","texto":"Para efectos del presente Contrato, los siguientes términos tendrán el significado que aquí se les asigna:"},{"tipo":"literal","texto":"a) Obra: el proyecto identificado en las Condiciones Particulares."},{"tipo":"literal","texto":"b) Administrador de Obra: HABITATUM S.A.S., designada por el Contratante para dirigir la Obra y actuar en su nombre y representación frente al Contratista, en los términos de la Cláusula 3. Es la única instancia autorizada para impartir instrucciones al Contratista. No es parte de este Contrato."},{"tipo":"literal","texto":"c) Trabajos: las actividades, suministros e instalaciones objeto del Contrato, descritos en las Condiciones Particulares, el Anexo 1 (Cantidades y Precios) y el Anexo 2 (Condiciones Técnicas)."},{"tipo":"literal","texto":"d) Corte de Obra: medición conjunta, entre el Contratista y el Administrador de Obra, de los Trabajos ejecutados y recibidos a satisfacción en el periodo pactado, consignada en un acta que sirve de base para el pago."},{"tipo":"literal","texto":"e) Liberación: aprobación previa y escrita del Administrador de Obra, por bitácora, correo electrónico o mensaje escrito, antes de cubrir, vaciar u ocultar un trabajo."},{"tipo":"literal","texto":"f) Condiciones Particulares: el acápite II de este documento. En caso de contradicción prevalecen las Condiciones Particulares, luego las Condiciones Generales, luego el Anexo 2 y luego el Anexo 1."}]},{"numero":2,"titulo":"OBJETO","parrafos":[{"tipo":"parrafo","texto":"El Contratista se obliga para con el Contratante a ejecutar, por su cuenta y riesgo, con plena autonomía técnica, administrativa y financiera, y con su propio personal y herramienta, los Trabajos descritos en las Condiciones Particulares y en los Anexos 1 y 2, conforme a los planos, especificaciones e instrucciones del Administrador de Obra. Como contraprestación, el Contratante pagará directamente al Contratista el precio pactado."}]},{"numero":3,"titulo":"ADMINISTRADOR DE OBRA","parrafos":[{"tipo":"parrafo","texto":"El Contratante ha designado a HABITATUM S.A.S., NIT 900.896.011-0, como Administrador de Obra, quien actuará en nombre y representación del Contratante frente al Contratista en todo lo relativo a la ejecución de este Contrato. HABITATUM no es parte del Contrato, ni deudora, garante o empleadora, y no asume obligaciones de pago frente al Contratista. Por delegación del Contratante, el Administrador de Obra podrá:"},{"tipo":"literal","texto":"a) Dirigir técnicamente la ejecución de los Trabajos, impartir instrucciones, aprobar Liberaciones, muestras y procedimientos, y fijar el horario de la Obra."},{"tipo":"literal","texto":"b) Medir con el Contratista y aprobar los Cortes de Obra, y validar las facturas o cuentas de cobro antes de su pago por el Contratante."},{"tipo":"literal","texto":"c) Aprobar por escrito mayores cantidades y obras no previstas, con la autorización del Contratante."},{"tipo":"literal","texto":"d) Ordenar suspensiones, recibir los Trabajos y elaborar el Acta de Liquidación."},{"tipo":"literal","texto":"e) Verificar el cumplimiento de las obligaciones laborales y de seguridad del Contratista, y solicitar al Contratante la retención de pagos cuando no se acrediten."},{"tipo":"literal","texto":"f) Gestionar, por cuenta del Contratante, las garantías y los reclamos de postventa."},{"tipo":"parrafo","texto":"Parágrafo primero. Las instrucciones, aprobaciones y actas del Administrador de Obra obligan al Contratista como si provinieran directamente del Contratante. El Contratista no recibirá instrucciones de terceros ni ejecutará trabajos en el inmueble por fuera de este Contrato sin autorización del Administrador de Obra."},{"tipo":"parrafo","texto":"Parágrafo segundo. El Contratista exonera a HABITATUM de toda responsabilidad por la mora o el incumplimiento del Contratante en los pagos. Las indemnidades pactadas a favor del Contratante se extienden a HABITATUM. El cambio del Administrador de Obra se comunicará por escrito al Contratista."}]},{"numero":4,"titulo":"ALCANCE Y CONOCIMIENTO DE LA OBRA","parrafos":[{"tipo":"parrafo","texto":"El alcance comprende todo lo necesario para entregar los Trabajos completos, terminados y en correcto funcionamiento, aunque no esté expresamente descrito, cuando sea técnicamente indispensable y razonablemente previsible para un contratista experto en la especialidad."},{"tipo":"parrafo","texto":"El Contratista declara que visitó la Obra, revisó los planos, especificaciones, cantidades y condiciones de acceso, almacenamiento y horarios, y que su precio incluye todos los costos para ejecutar los Trabajos. No podrá alegar el desconocimiento de estas condiciones para reclamar mayores valores ni plazos."},{"tipo":"parrafo","texto":"Parágrafo. Si el Contratista advierte errores, omisiones o inconsistencias en planos o especificaciones, los informará por escrito al Administrador de Obra antes de ejecutar el trabajo afectado. Lo que ejecute sin consultar será corregido a su costo."}]},{"numero":5,"titulo":"VALOR Y PRECIOS","parrafos":[{"tipo":"parrafo","texto":"El valor del Contrato es el señalado en las Condiciones Particulares y se rige por precios unitarios fijos: el valor final será el resultado de multiplicar las cantidades realmente ejecutadas, medidas y recibidas a satisfacción por los precios unitarios del Anexo 1. Las mayores o menores cantidades se pagan o descuentan a los mismos precios unitarios."},{"tipo":"parrafo","texto":"Los precios son fijos y no reajustables durante el plazo y sus prórrogas, salvo pacto escrito. Incluyen mano de obra, salarios, prestaciones, seguridad social, dotación y elementos de protección personal, la herramienta y los equipos que estén a cargo del Contratista, transporte interno, aseo y retiro de sobrantes, administración, imprevistos, utilidad, pólizas y los tributos a su cargo."},{"tipo":"parrafo","texto":"Parágrafo. Las obras no previstas en el Anexo 1 solo se ejecutarán y pagarán con aprobación escrita previa del Administrador de Obra, que fije su precio y su efecto en el plazo. Lo ejecutado sin dicha aprobación no será reconocido."}]},{"numero":6,"titulo":"FORMA DE PAGO Y CORTES DE OBRA","parrafos":[{"tipo":"parrafo","texto":"Los Trabajos se pagarán mediante Cortes de Obra con la periodicidad y el plazo señalados en las Condiciones Particulares, así:"},{"tipo":"literal","texto":"a) Al cierre de cada periodo, el Contratista y el Administrador de Obra medirán conjuntamente en la Obra las cantidades ejecutadas, y el Administrador de Obra elaborará el acta de Corte de Obra. Solo se pagan Trabajos terminados, medidos y recibidos a satisfacción."},{"tipo":"literal","texto":"b) Son requisitos para cada pago: (i) el acta de Corte de Obra firmada por el Administrador de Obra y el Contratista; y (ii) factura electrónica a nombre del Contratante o, si el Contratista no está obligado a facturar, cuenta de cobro a su nombre."},{"tipo":"literal","texto":"c) El Contratante pagará directamente al Contratista dentro del plazo señalado en las Condiciones Particulares, contado desde la aprobación del corte y la entrega de los documentos. Mientras los documentos estén incompletos el plazo no corre ni se causan intereses."},{"tipo":"literal","texto":"d) De cada pago se descontarán la amortización del anticipo, la retención de garantía, las retenciones tributarias que correspondan y los demás valores a cargo del Contratista."},{"tipo":"literal","texto":"e) Los pagos se harán en efectivo o por transferencia bancaria a la cuenta del Contratista, según se acuerde para cada corte. Todo pago en efectivo constará en recibo firmado por el Contratista, que hará parte del acta de corte."},{"tipo":"parrafo","texto":"Parágrafo. HABITATUM no es deudora, garante ni pagadora de las sumas a cargo del Contratante; el único deudor del precio es el Contratante. La aprobación de un corte no implica recibo definitivo ni renuncia a reclamar por defectos."}]},{"numero":7,"titulo":"ANTICIPO","parrafos":[{"tipo":"parrafo","texto":"Si en las Condiciones Particulares se pacta anticipo, este se entregará una vez firmado el Contrato y aprobadas las garantías exigidas, con sujeción a las siguientes reglas:"},{"tipo":"literal","texto":"a) Se destinará exclusivamente a la Obra. No constituye pago ni transfiere al Contratista la propiedad de esos recursos hasta su amortización."},{"tipo":"literal","texto":"b) Se amortizará en cada Corte de Obra en el mismo porcentaje en que fue otorgado sobre el valor del Contrato, de modo que quede amortizado en su totalidad con el último corte."},{"tipo":"literal","texto":"c) Si el Contrato termina por cualquier causa con saldo sin amortizar, el Contratista lo reintegrará dentro de los cinco (5) días hábiles siguientes; en su defecto, se compensará con la retención de garantía y con cualquier saldo a su favor."}]},{"numero":8,"titulo":"RETENCIÓN DE GARANTÍA","parrafos":[{"tipo":"parrafo","texto":"De cada pago se retendrá el porcentaje señalado en las Condiciones Particulares como garantía del cumplimiento del Contrato, de la calidad de los Trabajos y de las obligaciones laborales del Contratista. La retención se devolverá, sin intereses, dentro de los treinta (30) días siguientes a la firma del Acta de Liquidación, previa entrega del paz y salvo de salarios, prestaciones y seguridad social de su personal, de las pólizas de estabilidad exigidas y la atención de los pendientes del recibo final."},{"tipo":"parrafo","texto":"Parágrafo. El Contratante podrá aplicar la retención, total o parcialmente, al pago de reparaciones, anticipo no amortizado u obligaciones laborales y de seguridad social insolutas del Contratista."}]},{"numero":9,"titulo":"PLAZO","parrafos":[{"tipo":"parrafo","texto":"El plazo de ejecución es el señalado en las Condiciones Particulares. El Contratista se ajustará a la programación general de la Obra que defina el Administrador de Obra y se coordinará con los demás contratistas."},{"tipo":"parrafo","texto":"Las prórrogas solo procederán mediante otrosí escrito, solicitadas antes del vencimiento del plazo y por causas no imputables al Contratista, tales como obras no previstas aprobadas, suspensiones ordenadas por el Administrador de Obra o fuerza mayor debidamente acreditada."},{"tipo":"parrafo","texto":"Parágrafo. Si el Contratista presenta atrasos imputables a él, el Administrador de Obra podrá exigirle aumentar cuadrillas o frentes de trabajo, sin costo adicional, hasta recuperar el atraso."}]},{"numero":10,"titulo":"OBLIGACIONES DEL CONTRATISTA","parrafos":[{"tipo":"parrafo","texto":"Además de las previstas en otras cláusulas y en el Anexo 2, el Contratista se obliga a:"},{"tipo":"literal","texto":"a) Ejecutar los Trabajos con calidad, empleando los materiales y procedimientos especificados, conforme a las normas técnicas aplicables (NSR-10, RETIE cuando corresponda, normas NTC y manuales del fabricante)."},{"tipo":"literal","texto":"b) Acatar únicamente las instrucciones del Administrador de Obra. Las solicitudes del Contratante, sus familiares o terceros se canalizarán a través del Administrador de Obra."},{"tipo":"literal","texto":"c) Designar un encargado permanente en la Obra, con autoridad suficiente para representarlo."},{"tipo":"literal","texto":"d) Disponer de personal idóneo, calificado y suficiente para cumplir el plazo."},{"tipo":"literal","texto":"e) Cumplir el horario de trabajo establecido para la Obra, señalado en las Condiciones Particulares o el que fije por escrito el Administrador de Obra. Aunque el Contratista ejecuta los Trabajos a precio y con autonomía, y no por nómina, la presencia y las labores de su personal en la Obra se sujetarán a dicho horario y no a su libre criterio. Los trabajos por fuera de él requerirán autorización previa del Administrador de Obra."},{"tipo":"literal","texto":"f) Solicitar la Liberación del Administrador de Obra antes de cubrir, vaciar u ocultar cualquier trabajo."},{"tipo":"literal","texto":"g) Cuidar y proteger lo ejecutado y las obras de otros contratistas hasta el recibo final, y reparar a su costo los daños que cause a la Obra, al inmueble, a vecinos o a terceros."},{"tipo":"literal","texto":"h) Mantener el aseo diario de sus frentes y retirar sobrantes y escombros propios al sitio que indique el Administrador de Obra."},{"tipo":"literal","texto":"i) Cumplir el reglamento interno de la Obra y, cuando aplique, el de la copropiedad o parcelación, incluidos accesos, ruido y manejo de residuos."},{"tipo":"literal","texto":"j) Asistir a las reuniones de obra a las que sea citado e informar oportunamente y por escrito los riesgos, defectos o inconsistencias que detecte."},{"tipo":"literal","texto":"k) Cumplir sus obligaciones laborales y de seguridad social, y mantener vigentes las garantías del Contrato."},{"tipo":"literal","texto":"l) Abstenerse de pernoctar en la Obra, de ingresar personas ajenas a sus labores y de publicar fotografías o videos de la Obra sin autorización escrita."}]},{"numero":11,"titulo":"MATERIALES, HERRAMIENTAS Y EQUIPOS","parrafos":[{"tipo":"literal","texto":"a) Materiales suministrados por el Contratante: el Contratista los solicitará por escrito al Administrador de Obra con una anticipación mínima de tres (3) días hábiles; recibirá y firmará las remisiones; responderá por su custodia, buen uso y pérdida desde su entrega; y devolverá los sobrantes. Las pérdidas y los materiales dañados por mal uso se descontarán a precio de reposición."},{"tipo":"literal","texto":"b) Materiales a cargo del Contratista, cuando así se indique en las Condiciones Particulares o en el Anexo 1: serán nuevos, de primera calidad, de las referencias aprobadas y con fichas técnicas. El riesgo sobre ellos es del Contratista hasta el recibo de los Trabajos."},{"tipo":"literal","texto":"c) Herramientas y equipos: el Contratista aporta su herramienta, en buen estado y con las certificaciones que exija la actividad. Los equipos que, según las Condiciones Particulares, suministre la Obra los recibirá con acta, responderá por su custodia y buen uso mientras estén a su cargo y los devolverá en el estado en que los recibió, salvo el desgaste normal. El Contratante y HABITATUM no responden por la pérdida, hurto o daño de las herramientas o pertenencias del Contratista o de su personal."}]},{"numero":12,"titulo":"CALIDAD, INSPECCIÓN Y RECHAZO","parrafos":[{"tipo":"parrafo","texto":"El Administrador de Obra podrá inspeccionar los Trabajos en cualquier momento y ordenar los ensayos que considere necesarios. Los Trabajos defectuosos o que no cumplan las especificaciones serán demolidos, retirados o rehechos por el Contratista, a su costo, dentro del plazo que fije el Administrador de Obra. Si no lo hace, el Contratante podrá ejecutarlos por medio de terceros y descontará su costo más un diez por ciento (10 %) de cualquier saldo a favor del Contratista. La aprobación de cortes o liberaciones no exonera al Contratista de su responsabilidad por defectos o vicios ocultos."}]},{"numero":13,"titulo":"PERSONAL E INDEPENDENCIA","parrafos":[{"tipo":"parrafo","texto":"El Contratista es un contratista independiente en los términos del artículo 34 del Código Sustantivo del Trabajo. Ejecutará el Contrato con plena autonomía técnica y directiva, y será el único empleador o contratante del personal que vincule. Entre el Contratante, HABITATUM y el personal del Contratista no existirá vínculo laboral alguno."},{"tipo":"literal","texto":"a) El Contratista afiliará y pagará oportunamente a todo su personal a salud, pensión y riesgos laborales, y pagará salarios no inferiores al mínimo legal, prestaciones sociales e indemnizaciones."},{"tipo":"literal","texto":"b) Si el Contratista no acredita el pago de salarios o seguridad social cuando se le solicite, el Contratante podrá retener los pagos y pagar directamente a los trabajadores y a las entidades de seguridad social, con cargo a cualquier saldo a favor del Contratista."},{"tipo":"literal","texto":"c) Está prohibido el trabajo de menores de edad."},{"tipo":"parrafo","texto":"Parágrafo. El Contratista mantendrá indemnes al Contratante y a HABITATUM frente a cualquier reclamación laboral o de seguridad social originada en su personal, incluidas las derivadas de la solidaridad prevista en el artículo 34 del Código Sustantivo del Trabajo."}]},{"numero":14,"titulo":"SEGURIDAD Y SALUD EN EL TRABAJO","parrafos":[{"tipo":"parrafo","texto":"El Contratista cumplirá las normas de seguridad y salud en el trabajo aplicables a su actividad y, cuando aplique, las de trabajo seguro en alturas de la Resolución 4272 de 2021. En especial se obliga a:"},{"tipo":"literal","texto":"a) Antes del ingreso de cada trabajador, acreditar su afiliación vigente a la ARL, los certificados de trabajo en alturas cuando aplique y la entrega de dotación y elementos de protección personal."},{"tipo":"literal","texto":"b) Reportar de inmediato al Administrador de Obra, y a la ARL dentro del término legal, todo accidente o incidente de trabajo."},{"tipo":"parrafo","texto":"Parágrafo. El Administrador de Obra podrá suspender actividades o exigir el retiro de trabajadores que incumplan las normas de seguridad, sin que ello genere prórroga del plazo ni costos adicionales."}]},{"numero":15,"titulo":"GARANTÍAS Y PÓLIZAS","parrafos":[{"tipo":"parrafo","texto":"Dentro de los cinco (5) días hábiles siguientes a la firma, y como requisito para el primer pago, el Contratista constituirá a su costo, con una compañía de seguros vigilada por la Superintendencia Financiera de Colombia y en formato para contratos entre particulares, las garantías indicadas en la sección III, en favor del Contratante como asegurado y beneficiario y, cuando la aseguradora lo permita, de HABITATUM S.A.S. como beneficiario adicional. En la póliza de responsabilidad civil extracontractual figurarán como asegurados adicionales el Contratante y HABITATUM S.A.S."},{"tipo":"literal","texto":"a) Las pólizas deberán ser aprobadas por el Administrador de Obra y acompañarse del recibo de pago de la prima."},{"tipo":"literal","texto":"b) El Contratista ampliará valores y vigencias dentro de los cinco (5) días hábiles siguientes a cualquier otrosí que aumente el valor o el plazo."},{"tipo":"literal","texto":"c) La póliza de responsabilidad civil extracontractual incluirá predios, labores y operaciones, responsabilidad civil patronal y contratistas y subcontratistas."},{"tipo":"parrafo","texto":"Parágrafo. Las garantías no limitan la responsabilidad del Contratista. Mientras no se entreguen y aprueben no se efectuarán pagos."}]},{"numero":16,"titulo":"COMPENSACIÓN Y DESCUENTOS","parrafos":[{"tipo":"parrafo","texto":"El Contratista autoriza de manera expresa e irrevocable al Contratante para descontar de cualquier suma a su favor los valores por anticipo no amortizado, reparaciones, pérdida o daño de materiales y equipos, daños a la Obra o a terceros, pagos laborales o de seguridad social efectuados por su cuenta y demás sumas que se deriven de su incumplimiento, operando la compensación conforme al artículo 1714 del Código Civil."}]},{"numero":17,"titulo":"ENTREGA, RECIBO Y LIQUIDACIÓN","parrafos":[{"tipo":"parrafo","texto":"Terminados los Trabajos, el Administrador de Obra y el Contratista suscribirán el Acta de Recibo Final, con la lista de pendientes y el plazo para atenderlos; el recibo no implica renuncia a reclamar por vicios ocultos. Dentro de los treinta (30) días siguientes se suscribirá el Acta de Liquidación, con el valor final ejecutado, los pagos, los descuentos y los saldos, previa entrega del paz y salvo de su personal y de la póliza de estabilidad. Si el Contratista no la firma dentro de los diez (10) días hábiles siguientes a su envío, el Contrato podrá liquidarse unilateralmente."}]},{"numero":18,"titulo":"GARANTÍA DE LOS TRABAJOS Y POSTVENTA","parrafos":[{"tipo":"parrafo","texto":"El Contratista garantiza la calidad y el correcto funcionamiento de los Trabajos durante el plazo señalado en las Condiciones Particulares, contado desde el Acta de Recibo Final, sin perjuicio de las pólizas y de la responsabilidad prevista en el artículo 2060 del Código Civil."},{"tipo":"literal","texto":"a) Atenderá cada reclamo iniciando la corrección dentro de los días hábiles señalados en las Condiciones Particulares, contados desde el aviso escrito, y dentro de las veinticuatro (24) horas siguientes en casos urgentes."},{"tipo":"literal","texto":"b) Si no lo hace, el Contratante podrá ejecutar la corrección por terceros y cobrar su costo más un diez por ciento (10 %), con cargo a la retención de garantía, las pólizas o cualquier saldo a favor del Contratista."}]},{"numero":19,"titulo":"RESPONSABILIDAD E INDEMNIDAD","parrafos":[{"tipo":"parrafo","texto":"El Contratista responde por los daños que él, su personal o sus subcontratistas causen a la Obra, al inmueble, a las obras de otros contratistas, a vecinos y a terceros, y conservará la custodia y el riesgo de los Trabajos hasta el recibo final. Mantendrá indemnes al Contratante y a HABITATUM frente a toda reclamación, sanción o perjuicio que se origine en sus actos u omisiones, y asumirá su defensa."}]},{"numero":20,"titulo":"SUSPENSIÓN","parrafos":[{"tipo":"parrafo","texto":"El Administrador de Obra podrá suspender total o parcialmente los Trabajos por necesidades de la Obra, por instrucción del Contratante, por incumplimiento de las normas de seguridad o por fuerza mayor, mediante acta, y el plazo se suspenderá por el mismo tiempo. Las suspensiones no generan pagos por tiempos muertos ni sobrecostos; si una no imputable al Contratista supera treinta (30) días, este podrá pedir la terminación con el pago de lo ejecutado."}]},{"numero":21,"titulo":"TERMINACIÓN","parrafos":[{"tipo":"parrafo","texto":"El Contrato terminará por las siguientes causas:"},{"tipo":"literal","texto":"a) Ejecución total del objeto y firma del Acta de Liquidación."},{"tipo":"literal","texto":"b) Mutuo acuerdo de las Partes, que constará por escrito."},{"tipo":"literal","texto":"c) Decisión unilateral del Contratante, en cualquier momento, incluida la decisión de suspender definitivamente o no continuar la Obra, con aviso escrito de cinco (5) días hábiles, pagando únicamente lo ejecutado y recibido, sin indemnización por lucro cesante."},{"tipo":"literal","texto":"d) Incumplimiento grave del Contratista, entre otros: abandono de la Obra por más de tres (3) días hábiles; atraso imputable superior al quince por ciento (15 %) del plazo; no constituir las garantías; no pagar salarios o seguridad social; incumplimientos reiterados de seguridad; cesión o subcontratación no autorizadas; o inicio de un proceso de insolvencia."},{"tipo":"literal","texto":"e) Por el Contratista, en caso de mora del Contratante superior a treinta (30) días en el pago de cortes aprobados, previo requerimiento escrito con diez (10) días hábiles de antelación."},{"tipo":"parrafo","texto":"Parágrafo. En la terminación por incumplimiento del Contratista, el Contratante podrá continuar los Trabajos por medio de terceros, y el mayor costo que ello genere y los perjuicios causados serán a cargo del Contratista."}]},{"numero":22,"titulo":"CESIÓN Y SUBCONTRATACIÓN","parrafos":[{"tipo":"parrafo","texto":"El Contratista no podrá ceder el Contrato ni subcontratar total o parcialmente los Trabajos sin autorización previa y escrita del Administrador de Obra; aun autorizado, responderá solidariamente por sus subcontratistas."}]},{"numero":23,"titulo":"SOLUCIÓN DE CONTROVERSIAS","parrafos":[{"tipo":"parrafo","texto":"Las diferencias que surjan del Contrato se resolverán, en primer lugar, por arreglo directo dentro de los quince (15) días hábiles siguientes a la solicitud escrita de una Parte. Si no hay acuerdo, cualquiera de las Partes podrá acudir a los mecanismos de solución de conflictos y a la jurisdicción ordinaria colombiana."}]}],"firmas":{"texto_previo":"Las Partes manifiestan su conformidad con el presente Contrato, sus Condiciones Particulares, Condiciones Generales y anexos, y lo suscriben en el lugar y la fecha indicados en las Condiciones Particulares.","bloques":"Un bloque 'EL CONTRATANTE' por cada propietario (NOMBRE en mayúsculas + C.C.) y un bloque 'EL CONTRATISTA' (NOMBRE + C.C. o NIT). Dos bloques por fila. HABITATUM no firma."},"anexo_1":{"titulo":"Anexo 1 · Cantidades y precios","seccion_A":"Cuadro de cantidades y precios: Ítem | Descripción | Un | Cant. | V. unitario | V. total; luego Subtotal, Régimen, A, I, U, IVA (en AIU solo sobre la U) y VALOR TOTAL DEL CONTRATO","nota_A":"Cantidades estimadas. Se pagan las cantidades realmente ejecutadas, medidas y recibidas, a los precios unitarios fijos de este anexo.","seccion_B":"Precios unitarios de referencia (sin cantidad contratada): ítems marcados como 'referencia'; muestran solo V. unitario y no suman al valor del contrato","nota_B":"Solo se ejecutan y pagan con orden escrita previa del Administrador de Obra que fije la cantidad. Las horas se soportan con planilla diaria firmada por el Administrador de Obra. No suman al valor del contrato.","firmas":["El Contratante","El Contratista"]},"anexo_2":{"titulo":"Anexo 2 · Condiciones técnicas","A_requisitos_previos":["RUT actualizado del Contratista.","Copia de la cédula del Contratista (persona natural) o certificado de existencia y representación legal y cédula del representante (persona jurídica).","Certificación bancaria, cuando los pagos se hagan por transferencia.","Pólizas exigidas en la sección III del Contrato, con el recibo de pago de la prima.","Listado del personal con afiliación vigente a salud, pensión y ARL.","Certificados vigentes de trabajo en alturas, cuando aplique.","Fichas técnicas y muestras aprobadas, cuando el Contratista suministre materiales."],"B_obligaciones_generales":["Recibir los frentes y soportes de trabajo mediante acta, dejando constancia de defectos previos. Iniciar un frente sin reportar defectos implica la aceptación del soporte.","Ejecutar conforme a los planos, especificaciones, NSR-10, normas técnicas aplicables y manuales del fabricante, cumpliendo las tolerancias de plomo, nivel, escuadra y alineamiento especificadas.","Solicitar la Liberación del Administrador de Obra antes de cubrir, vaciar u ocultar cualquier trabajo, y antes de iniciar cada frente que la requiera.","Presentar muestras o ejecutar un tramo de prueba cuando el Administrador de Obra lo solicite; el trabajo debe igualar la muestra aprobada.","Coordinar con los demás oficios los elementos embebidos, pases y remates. Prohibido romper, perforar o regatear elementos estructurales sin autorización escrita del Administrador de Obra.","Controlar los materiales recibidos: firmar remisiones, almacenarlos en orden, usarlos racionalmente y devolver los sobrantes.","Proteger lo ejecutado y las obras de otros oficios (carpinterías, aparatos, ventanería, pisos); los daños corren por su cuenta.","Mantener el aseo diario de sus frentes y retirar los escombros propios al sitio autorizado.","Realizar con acta las pruebas que exija su actividad (estanqueidad, presión, funcionamiento, nivelación) antes del recibo.","En trabajos en alturas, cumplir la Resolución 4272 de 2021: personal certificado, permisos de trabajo, anclajes y equipos certificados.","Corregir a su costo los defectos atribuibles a la ejecución, durante la Obra y el período de garantía.","Entregar fichas técnicas, garantías del fabricante y manuales de lo suministrado o instalado, cuando aplique.","Atender los retoques y la lista de pendientes del recibo dentro del plazo fijado en el acta."],"C_obligaciones_particulares":"Lista editable por contrato; numeración continúa después de la sección B. Si está vacía, se omite la sección C.","cierre":"Lo anterior sin perjuicio de los planos, especificaciones y normas técnicas aplicables, que prevalecen en lo que sean más exigentes.","firma":"El Contratista – recibido y aceptado"}}$j$::jsonb);
